#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q, K;
    cin >> N >> Q >> K;

    vector<ll> A(N + 1);
    for (int i = 1; i <= N; ++i) cin >> A[i];

    vector<int> D(Q);
    for (int i = 0; i < Q; ++i) cin >> D[i];

    const int INF = Q + 1;
    vector<int> T(N + 1, INF);
    for (int t = 1; t <= Q; ++t) {
        T[D[t - 1]] = t;
    }

    vector<ll> p(N + 1), q(N + 1);
    unordered_map<ll, vector<int>, custom_hash> pMap, qMap;
    pMap.reserve(N * 2);
    qMap.reserve(N * 2);

    for (int i = 1; i <= N; ++i) {
        p[i] = (ll)i + A[i];
        q[i] = (ll)i - A[i];
        pMap[p[i]].push_back(i);
        qMap[q[i]].push_back(i);
    }

    auto countP = [&](ll V, int L, int R) -> ll {
        if (L > R) return 0;
        auto it = pMap.find(V);
        if (it == pMap.end()) return 0;
        const auto& vec = it->second;
        auto it1 = lower_bound(vec.begin(), vec.end(), L);
        auto it2 = upper_bound(vec.begin(), vec.end(), R);
        return it2 - it1;
    };

    auto countQ = [&](ll V, int L, int R) -> ll {
        if (L > R) return 0;
        auto it = qMap.find(V);
        if (it == qMap.end()) return 0;
        const auto& vec = it->second;
        auto it1 = lower_bound(vec.begin(), vec.end(), L);
        auto it2 = upper_bound(vec.begin(), vec.end(), R);
        return it2 - it1;
    };

    ll total = 0;
    for (int i = 1; i <= N; ++i) {
        int lo = i + 1;
        int hi = min(N, i + K - 1);
        if (lo <= hi) {
            total += countP(p[i] + K, lo, hi);
            total += countQ(q[i] + K, lo, hi);
        }
        ll j = (ll)i + K;
        if (j <= N && A[i] == A[j]) total++;
    }

    if (Q == 0) {
        cout << total << "\n";
        return 0;
    }

    // Build Cartesian tree of T (min-heap)
    vector<int> left(N + 1, 0), right(N + 1, 0);
    vector<int> st;
    st.reserve(N);
    for (int i = 1; i <= N; ++i) {
        int last = 0;
        while (!st.empty() && T[st.back()] > T[i]) {
            last = st.back();
            st.pop_back();
        }
        if (last) left[i] = last;
        if (!st.empty()) right[st.back()] = i;
        st.push_back(i);
    }
    int root = st[0];

    vector<int> L(N + 1), R(N + 1);
    vector<int> order;
    order.reserve(N);
    stack<int> stk;
    stk.push(root);
    while (!stk.empty()) {
        int u = stk.top();
        stk.pop();
        order.push_back(u);
        if (left[u]) stk.push(left[u]);
        if (right[u]) stk.push(right[u]);
    }
    for (int idx = (int)order.size() - 1; idx >= 0; --idx) {
        int u = order[idx];
        L[u] = R[u] = u;
        if (left[u]) {
            L[u] = min(L[u], L[left[u]]);
            R[u] = max(R[u], R[left[u]]);
        }
        if (right[u]) {
            L[u] = min(L[u], L[right[u]]);
            R[u] = max(R[u], R[right[u]]);
        }
    }

    vector<ll> loss(Q + 1, 0);

    for (int i = 1; i <= N; ++i) {
        if (T[i] <= Q) {
            int t = T[i];
            int d = i;
            int l = L[i], r = R[i];
            ll cross = 0;
            int left_size = d - l + 1;
            int right_size = r - d + 1;

            if (left_size <= right_size) {
                for (int x = l; x <= d; ++x) {
                    int lo = d;
                    int hi = min(r, x + K - 1);
                    if (lo <= hi) {
                        cross += countP(p[x] + K, lo, hi);
                        cross += countQ(q[x] + K, lo, hi);
                    }
                    ll y = (ll)x + K;
                    if (y >= d && y <= r && A[x] == A[(int)y]) cross++;
                }
            } else {
                for (int x = d; x <= r; ++x) {
                    int lo = max(l, x - K + 1);
                    int hi = d;
                    if (lo <= hi) {
                        cross += countP(p[x] - K, lo, hi);
                        cross += countQ(q[x] - K, lo, hi);
                    }
                    ll y = (ll)x - K;
                    if (y >= l && y <= d && A[x] == A[(int)y]) cross++;
                }
            }
            loss[t] = cross;
        }
    }

    cout << total << "\n";
    for (int t = 1; t <= Q; ++t) {
        total -= loss[t];
        cout << total << "\n";
    }

    return 0;
}
